"""Collect the checksummed Member 1 deliverables package (valid runs only) into ../deliverables/member1/ and write SUMMARY.md /
results_summary.json from the saved JSON evidence. Usage (from BEVFormer/): python3 -m outage.collect_deliverables"""
import hashlib, json, os, shutil, subprocess
P = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(os.path.dirname(P), "deliverables", "member1")
J = lambda p: json.load(open(os.path.join(P, p)))
RUNS = ["pilot_a", "pilot_b", "pilot_d05", "pilot_d10", "pilot_d20", "val_a", "val_b", "val_d05", "val_d10", "val_d20"]
EVAL = ["val_a", "val_b", "val_d05", "val_d10", "val_d20"]


def main():
    if os.path.exists(OUT):
        shutil.rmtree(OUT)
    os.makedirs(OUT)
    copy = ["README.md", "MODELS.md", "STORAGE_PLAN.md", "process.txt", "outage", "artifacts/run_matrix.sh", "artifacts/run_queue.sh",
            "artifacts/schedule_trainval_train.json", "artifacts/schedule_trainval_val.json", "artifacts/infos",
            "artifacts/provenance", "artifacts/data_inventory.json", "artifacts/verification_pilot.json",
            "artifacts/verification_val.json", "artifacts/isolation_pilot.json", "artifacts/input_probe",
            "artifacts/state_contamination_pilot.json", "artifacts/state_contamination_val.json", "artifacts/code_regression.json", "artifacts/cross_model_outage_check.json",
            "artifacts/logs/status.txt", "artifacts/canbus_audit_pilot.json", "artifacts/canbus_audit_val.json",
            "artifacts/loader_manifests.json", "artifacts/backbone_hook_probe.json", "artifacts/run_backup.sh",
            "artifacts/runs_backup", "artifacts/eval_backup/val_a/metrics.json", "artifacts/eval_backup/val_a/pts_bbox/metrics_summary.json"]
    copy += [f"artifacts/runs/{r}" for r in RUNS] + [f"artifacts/eval/{r}/metrics.json" for r in EVAL] + \
            [f"artifacts/eval/{r}/pts_bbox/metrics_summary.json" for r in EVAL]
    for c in copy:
        s, d = os.path.join(P, c), os.path.join(OUT, c)
        if not os.path.exists(s):
            raise SystemExit(f"missing deliverable {c}")
        os.makedirs(os.path.dirname(d), exist_ok=True)
        (shutil.copytree(s, d, ignore=shutil.ignore_patterns("__pycache__")) if os.path.isdir(s) else shutil.copy2(s, d))
    vp, vv, iso = J("artifacts/verification_pilot.json"), J("artifacts/verification_val.json"), J("artifacts/isolation_pilot.json")
    m = {r: J(f"artifacts/eval/{r}/metrics.json") for r in EVAL}
    k = "pts_bbox_NuScenes/"
    gate = dict(NDS=m["val_a"][k + "NDS"], mAP=m["val_a"][k + "mAP"], ref_NDS=0.354, ref_mAP=0.252, tol=0.010)
    gate["PASS"] = abs(gate["NDS"] - 0.354) <= 0.010 and abs(gate["mAP"] - 0.252) <= 0.010
    rr = {r: J(f"artifacts/runs/{r}/run.json") for r in RUNS}
    res = dict(baseline_gate=gate, official={r: {x: m[r][k + x] for x in ("NDS", "mAP", "mATE", "mASE", "mAOE", "mAVE", "mAAE")} for r in EVAL},
               verification_pilot={kk: v for kk, v in vp.items() if kk != "conditions"}, verification_val={kk: v for kk, v in vv.items() if kk != "conditions"},
               isolation={kk: v for kk, v in iso.items() if kk != "per_scene_alone_vs_continuous"},
               runs={r: dict({x: rr[r][x] for x in ("n_samples", "runtime_s", "latency_median_s", "peak_gpu_mb", "audit_status", "readiness",
                                                     "bev_history_present_after_first_frame", "tf32_matmul", "ckpt_sha256")},
                          fresh_at_all_scene_starts=all(f for _, f in rr[r]["model_state_fresh_at_scene_starts"])) for r in RUNS})
    json.dump(res, open(os.path.join(OUT, "results_summary.json"), "w"), indent=1)
    L = ["# Member 1 deliverables — BEVFormer-tiny clean/outage adapter, shared data inventory, checkpoint records\n",
         "Generated by `python3 -m outage.collect_deliverables`. Details, methods and limitations: `README.md`; checkpoints/envs: `MODELS.md`; storage: `STORAGE_PLAN.md`.\n",
         f"## Baseline gate (declared before the result: artifacts/provenance/BASELINE_GATE_DECLARATION.txt)\nNDS {gate['NDS']:.4f} / mAP {gate['mAP']:.4f} vs released 0.354 / 0.252 (tolerance ±0.010) -> **{'PASS' if gate['PASS'] else 'FAIL'}**\n",
         "## Official nuScenes metrics, full validation (150 scenes, 6019 samples), whole-sequence\n| run | NDS | mAP | mATE | mASE | mAOE | mAVE | mAAE |\n|---|---|---|---|---|---|---|---|"]
    for r in EVAL:
        o = res["official"][r]; L.append(f"| {r} | " + " | ".join(f"{o[x]:.4f}" for x in ("NDS", "mAP", "mATE", "mASE", "mAOE", "mAVE", "mAAE")) + " |")
    L.append("\nWhole-sequence scores dilute a brief single-camera outage; no significance is claimed here (event curves/bootstrap: Members 3/4).\n")
    for name, v in (("Pilot (10 training-split scenes, 402 samples)", vp), ("Full validation (150 scenes, 6019 samples)", vv)):
        L += [f"## {name}\nClean twice: max |diff| = {v['clean_twice_max_abs_diff']} over {v['clean_twice_identical_samples']} samples; clean audits {v['clean_audit_a']}/{v['clean_audit_b']}; paired input errors {v['clean_a_vs_b_input_errors']}.\n",
              "| outage | audit | paired-input errors | black = independent recomputation | black images | all-black pixels | other cams touched | prefix preds identical | post-start preds changed | scenes w/ missing bins |",
              "|---|---|---|---|---|---|---|---|---|---|"]
        for n, c in v["conditions"].items():
            L.append(f"| {n} | {c['status']} | {c['n_paired_errors']} | {c['black_inputs_expected_vs_logged_equal']} | {c['n_black_images']} | {c['all_black_pixels_verified']} | "
                     f"{c['other_cameras_corrupted']} | {c['prefix_predictions_identical']}/{c['prefix_samples']} | {c['post_start_predictions_changed']}/{c['post_start_samples']} | {len(c['missing_follow_up_bins'])} |")
        L.append("")
    L += [f"## Real-model state isolation (pilot, 10 scenes)\nall_isolated = {iso['all_isolated']}; each scene alone == continuous run (max diffs "
          f"{sorted({v['max_abs_diff'] for v in iso['per_scene_alone_vs_continuous'].values()})}); fresh B twice {iso['fresh_B_twice_max_abs_diff']}; "
          f"B after A {iso['B_after_A_vs_fresh_B_max_abs_diff']}; forced leak changes B by {iso['leak_unguarded_max_abs_diff_vs_fresh']:.1f} and is rejected ({iso['leak_control']['rejected_by_guard']}); "
          f"interleave rejected ({iso['interleave_control']['rejected']}); upstream hazard without explicit run reset (same scene re-run): prev_bev reused = "
          f"{iso['no_reset_rerun_same_scene']['prev_bev_reused_at_first_frame']}, diff {iso['no_reset_rerun_same_scene']['max_abs_diff_vs_fresh']:.1f} -> runner resets explicitly.\n",
          "## Model-input probe (exact tensors given to the backbone)\n" + "; ".join(
              f"d={J(f'artifacts/input_probe/input_probe_d{d}.json')['duration_s']}: PASS={J(f'artifacts/input_probe/input_probe_d{d}.json')['PASS']}" for d in ("0.5", "2")) + "\n",
          "## Review additions\n" + "\n".join([
              "* Backbone forward_pre_hook probe (real GPU inference): PASS=%s" % J("artifacts/backbone_hook_probe.json")["PASS"],
              "* CAN-bus causal audit: pilot max +%.1f ms, val max +%.1f ms, over 50 ms: %d / %d, values match: %s / %s" % (
                  J("artifacts/canbus_audit_pilot.json")["aux_offset_us"]["max"] / 1e3, J("artifacts/canbus_audit_val.json")["aux_offset_us"]["max"] / 1e3,
                  J("artifacts/canbus_audit_pilot.json")["aux_offset_us"]["n_over_policy"], J("artifacts/canbus_audit_val.json")["aux_offset_us"]["n_over_policy"],
                  J("artifacts/canbus_audit_pilot.json")["all_aux_match"], J("artifacts/canbus_audit_val.json")["all_aux_match"]),
              "* Backup BEVFormer-tiny_fp16, full val clean with the same adapter: NDS %.4f / mAP %.4f vs released 0.359 / 0.257 (±0.010, declared before) -> %s" % (
                  J("artifacts/eval_backup/val_a/metrics.json")[k + "NDS"], J("artifacts/eval_backup/val_a/metrics.json")[k + "mAP"],
                  "PASS" if abs(J("artifacts/eval_backup/val_a/metrics.json")[k + "NDS"] - 0.359) <= 0.010 and abs(J("artifacts/eval_backup/val_a/metrics.json")[k + "mAP"] - 0.257) <= 0.010 else "FAIL"),
              "* Exact loader manifests (val+pilot; SparseBEV replicated, 0 sweeps): artifacts/loader_manifests.json"]) + "\n",
          "## Runs\n| run | samples | runtime s | median latency s | peak GPU MB | audit | readiness | fresh at scene starts | BEV history used |\n|---|---|---|---|---|---|---|---|---|"]
    for r in RUNS:
        x = res["runs"][r]
        L.append(f"| {r} | {x['n_samples']} | {x['runtime_s']:.0f} | {x['latency_median_s']:.3f} | {x['peak_gpu_mb']:.0f} | {x['audit_status']} | {x['readiness'][:45]} | {x['fresh_at_all_scene_starts']} | {x['bev_history_present_after_first_frame']} |")
    L.append("\nLatency here is end-to-end per frame (JPEG decode + pipeline + model, 3 concurrent processes), NOT the isolated batch-one GPU latency (Member 4's profiling).")
    open(os.path.join(OUT, "SUMMARY.md"), "w").write("\n".join(L) + "\n")
    files = sorted(os.path.relpath(os.path.join(r, f), OUT) for r, _, fs in os.walk(OUT) for f in fs)
    with open(os.path.join(OUT, "SHA256SUMS"), "w") as f:
        for p in files:
            f.write(f"{hashlib.sha256(open(os.path.join(OUT, p), 'rb').read()).hexdigest()}  {p}\n")
    print("\n".join(L[:12])); print(len(files), "files ->", OUT)
    print(subprocess.run(["du", "-sh", OUT], capture_output=True, text=True).stdout)


if __name__ == "__main__":
    main()
